<?php
function stub($mode,$scenario){$cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__DIR__.'/stub.php').' '.escapeshellarg($mode).' '.escapeshellarg($scenario);exec($cmd,$lines,$code);check($code===0,'stub exit');return json_decode(implode("\n",$lines),true,512,JSON_THROW_ON_ERROR);}
$tests['T-12']=function(){foreach(['off','unset']as$s){$r=stub('uninstall',$s);eq($r['calls']??null,[],'retain nested '.$s.' despite legacy true');}};
$tests['T-13']=function(){foreach(['active','inactive','failure']as$s){$r=stub('uninstall',$s);eq($r['calls']??null,[],'retain dependent '.$s);check(!isset($r['exception']),'discovery failure handled safely');}$r=stub('uninstall','none');eq($r['calls']??null,[['query','DROP TABLE IF EXISTS wp_cewp_prices'],['query','DROP TABLE IF EXISTS wp_cewp_roles'],['delete','cewp_db_version'],['delete','cewp_settings'],['delete','cewp_dps_migrated']],'only shared cleanup');};
function browser_probe(){exec('node '.escapeshellarg(__DIR__.'/admin-probe.js'),$lines,$code);check($code===0,'JS adapter exit');return json_decode(implode("\n",$lines),true,512,JSON_THROW_ON_ERROR);}
$tests['T-22']=function(){$r=stub('update','false');check(($r['status']??0)>=400,'false DB update must fail');check(!str_contains(json_encode($r),'SQLSTATE'),'no SQL leak');foreach(browser_probe()as$r){if(!in_array($r['scenario'],['network','unknown']))continue;eq($r['close'],false,'failure modal stays');check($r['safe'],'visible safe fallback');}};
$tests['T-24']=function(){foreach(browser_probe()as$r){eq($r['close'],false,$r['scenario'].' modal stays');check($r['safe'],'visible safe message');if(!in_array($r['scenario'],['network','unknown']))check($r['specific'],$r['scenario'].' duplicate specific');}};
$tests['T-25']=function(){global $fixture;check(!method_exists(CEWP\Database::class,'save_min_order'),'no min-order API');check(!method_exists(CEWP\Pricing::class,'render_wholesale_price_notice'),'no notice');check(!file_exists(dirname(__DIR__).'/assets/wholesale.js'),'no notice asset');admin_ctx();$d=rule(pid('plain'),'fixed',45,'date_exclusion',['date_from'=>'2000-01-01','date_to'=>'2099-01-01']);$r=api('POST','prices',$d);$row=CEWP\Database::get_price((int)($r->get_data()['id']??0));check($row!==null,'date row saved');if($row){eq($row->date_from,null,'REST dates discarded');eq($row->date_to,null,'REST dates discarded');}[$q]=csv_probe("product_id,scope_value,price_type,price_value,date_from,date_to\n".pid('plain').",csv_dates,fixed,46,2000-01-01,2099-01-01\n");eq($q['imported']??null,1,'CSV date row accepted');foreach(['min-order/wholesale','global-discounts','category-discounts','groups']as$route)eq(api('GET',$route)->get_status(),404,'excluded route '.$route);foreach(['wholesale','vip']as$c){ctx($c);update_option('cewp_settings',['min_orders'=>[$c=>['min_subtotal'=>10000,'min_qty_total'=>1000,'require_before_whl'=>1]]]);cart(pid('fixed'),1);wc_clear_notices();do_action('woocommerce_check_cart_items');do_action('woocommerce_checkout_process');eq(wc_get_notices(),[],'min order inactive');}};
